CREATE TABLE accounts (id UUID PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('CUSTOMER','STAFF','ADMIN')), auth_version INTEGER NOT NULL DEFAULT 0, verified BOOLEAN NOT NULL DEFAULT FALSE, blocked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE establishments (id UUID PRIMARY KEY, owner_id UUID NOT NULL UNIQUE REFERENCES accounts(id), name VARCHAR(150) NOT NULL, address VARCHAR(300) NOT NULL, contact VARCHAR(150) NOT NULL, working_hours VARCHAR(150) NOT NULL);
CREATE TABLE auth_challenges (id UUID PRIMARY KEY, account_id UUID REFERENCES accounts(id), purpose VARCHAR(20) NOT NULL CHECK (purpose IN ('REGISTER','LOGIN','RESET')), code_hash VARCHAR(100) NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, sent_at TIMESTAMP WITH TIME ZONE NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, consumed BOOLEAN NOT NULL DEFAULT FALSE);
CREATE INDEX challenges_account ON auth_challenges(account_id, purpose);
CREATE TABLE auth_throttle (email VARCHAR(254) PRIMARY KEY, attempts INTEGER NOT NULL, window_start TIMESTAMP WITH TIME ZONE NOT NULL);
